script:
mr = frappe.db.get_value("Maintenance Request", {"maintenance_log": doc.name}, "customer")
if mr:
    doc.custom__customer_email = frappe.db.get_value("Customer", mr, "email_id")

history = doc.get("custom_reschedule_history_table")
if history:
    last_row = history[-1]
    if last_row.is_rescheduled and  last_row.notification_send == 1:
        frappe.get_doc("Notification", "Reschedule Alert to Customer").send(doc)
        last_row.notification_send = 0

if doc.custom_quotation_status == "Approved":
    logs = frappe.get_all(
        "Asset Maintenance Log",
        filters={"custom_quotation": doc.name},
        pluck="name",
    )

    for log_name in logs:
        frappe.db.set_value(
            "Asset Maintenance Log",
            log_name,
            "custom_quotation_status",
            "Quotation approved",
        )

alerts = doc.get("custom_supervisor_alert")
if alerts:
    last_row = alerts[-1]
    if last_row.get("notification"):
        frappe.get_doc("Notification", "Supervisor Alert Notification").send(doc)
        last_row.notification = 0
